Sdb* process_elf_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!shdr || sz <= 0) {
        return NULL;
    }

    // Allocate memory for version definitions
    Elf_(Half) num_version_entries = sz / sizeof(Elf_Verdef);
    Elf_Verdef *verdefs = (Elf_Verdef*)malloc(sz);
    if (!verdefs) {
        return NULL;
    }

    // Retrieve section names
    const char *section_name = elf_strptr(bin->elf, shdr->sh_link, shdr->sh_name);
    if (!section_name) {
        free(verdefs);
        return NULL;
    }

    // Initialize a new database
    Sdb *db = sdb_new0();
    if (!db) {
        free(verdefs);
        return NULL;
    }

    // Iterate through version definitions
    Elf_Verdef *verdef = verdefs;
    for (Elf_(Half) i = 0; i < num_version_entries; ++i) {
        if (verdef->vd_version != VER_DEF_CURRENT) {
            sdb_free(db);
            free(verdefs);
            return NULL;
        }

        char key[128];
        snprintf(key, sizeof(key), "version.%d.flags", i);
        sdb_set(db, key, sdb_itoa(verdef->vd_flags), 0);

        snprintf(key, sizeof(key), "version.%d.ndx", i);
        sdb_set(db, key, sdb_itoa(verdef->vd_ndx), 0);

        snprintf(key, sizeof(key), "version.%d.hash", i);
        sdb_set(db, key, sdb_itoa(verdef->vd_hash), 0);

        Elf_Verdaux *aux = (Elf_Verdaux*)((char*)verdef + verdef->vd_aux);
        if (aux && aux->vda_name) {
            const char *name = elf_strptr(bin->elf, shdr->sh_link, aux->vda_name);
            if (name) {
                snprintf(key, sizeof(key), "version.%d.name", i);
                sdb_set(db, key, (char*)name, 0);
            }
        }

        verdef = (Elf_Verdef*)((char*)verdef + verdef->vd_next);
    }

    free(verdefs);
    return db;
}

Sdb* process_elf_version_info(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    // Allocate memory for version definitions
    Elf_(Half)* verdefs = NULL;
    verdefs = (Elf_(Half)*)malloc(sz);
    if (!verdefs) {
        return NULL;
    }

    // Retrieve section names and initialize a new database
    Sdb *db = sdb_new0();
    if (!db) {
        free(verdefs);
        return NULL;
    }

    // Process version definitions
    Elf_(Half)* end = verdefs + (sz / sizeof(Elf_(Half)));
    Elf_(Half)* curr = verdefs;

    while (curr < end) {
        Elf_(Half) version = *curr;
        if (version == 0) {
            break;
        }

        // Store version and any relevant auxiliary info
        char key[32];
        snprintf(key, sizeof(key), "version_%d", version);
        sdb_num_set(db, key, (ut64)version, 0);

        curr++;
    }

    free(verdefs);
    return db;
}

Sdb* process_elf_version_info(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!shdr || shdr->sh_size < sizeof(Elf_(Verdef))) {
        return NULL;
    }

    Elf_(Verdef)* verdef = (Elf_(Verdef)*)malloc(shdr->sh_size);
    if (!verdef) {
        return NULL;
    }

    if (elf_get_section_data(bin, shdr, verdef, sz) != sz) {
        free(verdef);
        return NULL;
    }

    Sdb *db = sdb_new0();
    if (!db) {
        free(verdef);
        return NULL;
    }

    for (Elf_(Verdef)* vd = verdef; (char*)vd < (char*)verdef + shdr->sh_size; vd = (Elf_(Verdef*)((char*)vd + vd->vd_next)) {
        char name[256];
        snprintf(name, sizeof(name), "ver.%u", vd->vd_version);

        if (!sdb_set(db, name, "1", 0)) {
            sdb_free(db);
            free(verdef);
            return NULL;
        }

        Elf_(Verdaux)* aux = (Elf_(Verdaux*)((char*)vd + vd->vd_aux));
        for (int i = 0; i < vd->vd_naux; ++i) {
            char aux_key[256];
            snprintf(aux_key, sizeof(aux_key), "ver.%u.aux.%d", vd->vd_version, i);
            if (!sdb_set(db, aux_key, (char*)aux->vda_name, 0)) {
                sdb_free(db);
                free(verdef);
                return NULL;
            }
            aux = (Elf_(Verdaux*)((char*)aux + aux->vda_next));
        }
    }

    free(verdef);
    return db;
}

